    }
    // ── 6. Annulation, déplacement d'un passage ──
    if (has(t, CANCEL)) {
        return escalate("Un client annule un rendez-vous.", quote, "C'est noté, je transmets l'annulation à l'artisan. Merci de nous avoir prévenus !", "Annulation de rendez-vous : transmise à l'artisan.");
    }
    if (has(t, MOVE)) {
        const slot = parseSlot(req.text, now);
        const wish = slot.day ? ` Souhait : ${humanDay(slot.day)}${slot.time ? ` à ${humanTime(slot.time)}` : ""}.` : "";
        return escalate("Un client veut déplacer un rendez-vous.", `${quote}${wish}`, "C'est noté. Je transmets votre demande à l'artisan, qui vous confirme le nouveau créneau très vite.", "Déplacement de rendez-vous : transmis à l'artisan.");
    }
    // ── 7. Coordonnées après une urgence ──
    if (ASK_URGENT_CONTACT.test(lastAssistant)) {
        return reply("Merci, c'est transmis. L'artisan vous rappelle au plus vite.", `Coordonnées données pour le dépannage urgent${PHONE_RE.test(req.text) ? " (numéro dans la conversation)" : ""}.`);
    }
    // ── 8. Suite d'une demande de travaux en cours ──
    if ([ASK_COMMUNE, ASK_WHEN, ASK_VISIT, ASK_CONTACT].some((re) => re.test(lastAssistant))) {
        return workRequest(req, now, { t, quote, lastAssistant, hasNumber });
    }
    // ── 9. Date de démarrage, durée : jamais d'engagement ──
    if (has(t, START)) {
        return escalate("Un client demande une date de démarrage ou une durée de chantier.", quote, "Cela dépend du chantier et du planning : je pose la question à l'artisan, qui vous répond très vite.", "Question sur un délai de chantier : transmise à l'artisan.");
    }
    // ── 10. Spécialités : « vous faites… ? » ──
    const trade = tradeOf(t);
    if (CAN_YOU.test(t) && trade) {
        if (has(norm(sp.specialites ?? ""), trade.keys)) {
            return reply(`Oui, la ${trade.label === "salle de bain" || trade.label === "cuisine" ? `rénovation de ${trade.label}` : trade.label} fait partie de nos spécialités. Souhaitez-vous que je note votre demande ?`, `Question sur ${trade.label} : spécialité de l'entreprise, réponse donnée.`);
        }
        return escalate(`Un client demande si vous faites : ${trade.label}.`, quote, "Je vérifie auprès de l'artisan et je reviens vers vous très vite.", "Question sur une spécialité : transmise à l'artisan.");
    }
    // ── 11. Nouvelle demande de travaux ──
    const acceptsOffer = /^(oui|volontiers|d accord)\b/.test(t) && /que je note votre demande/.test(lastAssistant);
    if (has(t, WORK) || (trade && t.length > 25) || acceptsOffer) {
        return workRequest(req, now, { t, quote, lastAssistant, hasNumber });
    }
    // ── 12. Zone d'intervention ──
    if (has(t, ZONE_Q)) {
        const zone = sp.zone?.trim();
        if (zone) {
            return reply(`Nous intervenons sur cette zone : ${zone}. Souhaitez-vous que je note votre demande ?`, "Zone d'intervention donnée à un client.");
        }
    }
    // ── 13. Horaires, adresse de l'entreprise ──
    if (has(t, HOURS)) {
        const hours = a.establishment?.openingHours || a.jobDescription?.hours;
        if (hours) {
            return reply(`L'entreprise est joignable ${hours}. En dehors de ces horaires, je note votre demande et je la transmets.`, "Horaires donnés à un client.");
        }
    }
    if (has(t, ADDRESS) || /\b(c est ou|ou etes vous situes)\b/.test(t)) {
        const addr = a.establishment?.address;
        if (addr)
            return reply(`L'entreprise est située au ${addr}.`, "Adresse de l'entreprise donnée à un client.");
    }
    // ── 14. Consignes du patron ──
    const matched = matchInstruction(instructions, req.text);
    if (matched) {
        return reply(sentence(matched), "Réponse donnée grâce à une de vos consignes.");
    }
    // ── 15. Politesse ──
    if (has(t, ["bonjour", "bonsoir", "salut", "allo"]) && t.length < 40) {
        return reply(`Bonjour ! Ici ${a.name}, ${a.role}. Je peux noter votre demande de travaux ou de dépannage. Que puis-je faire pour vous ?`, "Accueil d'un client.");
    }
    if (has(t, ["merci", "parfait", "super", "d accord", "ok", "tres bien", "a bientot", "bonne journee"]) && t.length < 60) {
        return reply("Avec plaisir. À bientôt !", "Échange terminé avec un client.");
    }
    // ── Sinon : il transmet, il n'invente pas ──
    return escalate("Une demande de client à traiter.", quote, "Merci pour votre message. Je le transmets à l'artisan, qui vous répond très vite.", "Demande de client : transmise à l'artisan.");
}
/**
 * Demande de travaux, une question à la fois. L'état se lit dans la
 * conversation : chaque réponse du client suit une de ses questions.
