function workRequest(req, now, c) {
    const sp = req.assistant.specifics ?? {};
    const history = req.history ?? [];
    const facts = factsOf(history, req.text);
    const nature = facts.nature ?? clip(req.text);
    const trade = tradeOf(norm(nature));
    const outside = trade && sp.specialites?.trim() && !has(norm(sp.specialites), trade.keys) ? " À vérifier : hors des spécialités indiquées." : "";
    const recap = [
        `Travaux : ${nature}`,
        facts.commune ? `commune : ${facts.commune}` : "",
        facts.when ? `souhaité : ${facts.when}` : "",
    ]
        .filter(Boolean)
        .join(" ; ");
    const busy = req.switches?.carnet_plein === true;
    // 1. Commune.
    if (!facts.commune) {
        const what = trade ? `des travaux ${/^[aeiouyéè]/i.test(trade.label) ? "d'" : "de "}${trade.label}` : "votre demande de travaux";
        return reply(`C'est noté : ${what}. Dans quelle commune se trouvent les travaux ?`, `Demande de travaux en cours. ${recap}.${outside}`, "rendez_vous");
    }
    // 2. Délai souhaité.
    if (!facts.when) {
        return reply(`Merci. Pour quand souhaitez-vous les travaux (au plus vite, dans le mois, d'ici quelques mois) ?`, `Demande de travaux en cours. ${recap}.${outside}`, "rendez_vous");
    }
    // 3. Passage pour le métré (ou transmission si le patron gère lui-même).
    if (!switchOn(req, "rendez_vous")) {
        return escalate("Une nouvelle demande de travaux.", `${recap}.${outside}`, `Merci, j'ai tout noté. Je transmets votre demande à l'artisan, qui vous recontacte très vite${c.hasNumber ? "" : " (pensez à me laisser un numéro)"}.`, `Nouvelle demande de travaux : ${clip(nature)}.`);
    }
    const slot = facts.visitText ? parseSlot(facts.visitText, now) : null;
    // « Mardi en fin de matinée » suffit pour un métré : heure indicative, l'artisan confirme.
    const approx = slot?.day && !slot.time && slot.part ? approxTime(norm(facts.visitText ?? ""), slot.part) : null;
    if (slot && approx)
        slot.time = approx.time;
    if (slot?.day && !slot.time) {
        const givesContact = PHONE_RE.test(req.text);
        // Coordonnées données, ou heure déjà demandée une fois : on note le jour, sans boucler.
        if (ASK_CONTACT.test(c.lastAssistant) || givesContact) {
            return appointment(`Merci, j'ai tout noté pour ${humanDay(slot.day)}. L'artisan vous confirme très vite l'heure de son passage.`, `Passage pour le métré ${humanDay(slot.day)}, heure à convenir. Coordonnées du chantier dans la conversation. ${recap}.${outside}`, null);
        }
        if (ASK_HOUR.test(c.lastAssistant)) {
            return appointment(`C'est noté pour ${humanDay(slot.day)} : l'artisan vous précisera l'heure en vous confirmant son passage. À quel nom, et quelle est l'adresse exacte du chantier${c.hasNumber ? "" : " (avec un numéro pour vous joindre)"} ?`, `Passage pour le métré ${humanDay(slot.day)}, heure à convenir. ${recap}.${outside}`, null);
        }
    }
    if (!slot || !slot.day || !slot.time) {
        // La question reprend toujours « passer voir le chantier pour le métré » : c'est ce qui relie la réponse suivante.
        const partial = slot?.day
            ? `Très bien : ${humanDay(slot.day)}. À quelle heure l'artisan peut-il passer voir le chantier pour le métré ?`
            : "";
        return appointment(partial ||
            `${busy ? "Notre planning est très chargé en ce moment : les délais de démarrage sont plus longs que d'habitude. " : "Merci. "}L'artisan peut passer voir le chantier pour le métré : quel jour et à quelle heure vous arrangeraient ?`, `Demande de travaux : ${recap}.${busy ? " Client prévenu que les délais sont plus longs." : ""}${outside}`, null);
    }
    if (isPast(slot, now)) {
        return appointment("Ce créneau est déjà passé. L'artisan peut passer voir le chantier pour le métré : quel autre jour et à quelle heure vous arrangeraient ?", "Passage pour le métré : date à préciser.", null);
    }
    // 4. Créneau donné → noté ; puis coordonnées.
    const when = approx
        ? `${humanDay(slot.day)} ${approx.label} (vers ${humanTime(slot.time)})`
        : `${humanDay(slot.day)} à ${humanTime(slot.time)}`;
    if (!ASK_CONTACT.test(c.lastAssistant)) {
        return appointment(`C'est noté : passage pour le métré ${when}. L'artisan vous le confirme très vite. À quel nom, et quelle est l'adresse exacte du chantier${c.hasNumber ? "" : " (avec un numéro pour vous joindre)"} ?`, `Passage pour le métré ${when}, à confirmer. ${recap}.${outside}`, parisToISO(slot.day, slot.time.h, slot.time.min));
    }
    // 5. Coordonnées reçues.
    return reply("Merci, j'ai tout noté. L'artisan vous confirme son passage très vite.", `Coordonnées du chantier reçues (dans la conversation). ${recap}.`, "rendez_vous");
}
// ── Outils ───────────────────────────────────────────────────────────────────
function tradeOf(t) {
    return TRADES.find((tr) => has(t, tr.keys)) ?? null;
}
/** Relit la conversation : chaque message client qui suit une de ses questions en est la réponse. */
/** Heure indicative d'un moment de la journée (« en fin de matinée » → 11h). */
function approxTime(t, part) {
    if (/\bfin de matinee\b/.test(t))
        return { time: { h: 11, min: 0 }, label: "en fin de matinée" };
    if (/\bdebut d apres midi\b/.test(t))
        return { time: { h: 14, min: 0 }, label: "en début d'après-midi" };
    if (/\bfin d apres midi\b/.test(t))
        return { time: { h: 17, min: 0 }, label: "en fin d'après-midi" };
    if (part === "matin")
        return { time: { h: 9, min: 0 }, label: "dans la matinée" };
    if (part === "apres-midi")
        return { time: { h: 14, min: 0 }, label: "dans l'après-midi" };
    return { time: { h: 18, min: 0 }, label: "en fin de journée" };
}
function factsOf(history, current) {
    const turns = [...history, { author: "client", text: current }];
    const facts = { nature: null, commune: null, when: null, visitText: null };
    let lastQuestion = "";
    for (const turn of turns) {
        if (turn.author === "assistant") {
            lastQuestion = norm(turn.text);
            continue;
        }
        if (turn.author !== "client")
            continue;
        if (ASK_COMMUNE.test(lastQuestion))
            facts.commune = clip(turn.text);
        else if (ASK_WHEN.test(lastQuestion))
            facts.when = clip(turn.text);
        else if (ASK_VISIT.test(lastQuestion))
            facts.visitText = `${facts.visitText ?? ""} ${turn.text}`.trim();
        else if (!facts.nature && (has(norm(turn.text), WORK) || tradeOf(norm(turn.text))))
            facts.nature = clip(turn.text);
        lastQuestion = "";
    }
    return facts;
}

